"""1357 (#11, pickup_loot_steal): Record-Coverage-v1356.ps1 with pickpocket and bodyloot on tutorial guard 2, who carries a
key on his belt (takedown-variants-v1254h showed its Pickpocket prompt). Both wait (up to 150 s) until he stands still at his
44 s patrol pause near (-47.95, -152.45), hold the free camera 3.6 m ahead of him looking back, and crouch the source.
- pickpocket: the source stands at his right side (0.85 m beside, 0.4 m behind, facing him, looking down 20 degrees) and
  taps X; the native steal must play (LootObject47) and the source's inventory must gain an item.
- bodyloot: the source chokes him from behind (RightShoulder held), then looks down at the body and taps X; the native
  loot must play (LootObject47).
In both the partner must present the generic use reach (use variant 1, 1214j). Generated by make_coverage_v1357.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1356.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:100])
    s = s.replace(old, new)

rep("# 1356 (#11):", "# 1357 (#11): pickpocket and bodyloot on the standing tutorial guard. Generated by make_coverage_v1357.py.\n# 1356 (#11):")
rep("[string]$Take='coverage-v1356a'", "[string]$Take='coverage-v1357a'")
rep("'blinkcancel','kickledge','kickledge2')", "'blinkcancel','kickledge','kickledge2','pickpocket','bodyloot')")
rep("'dominolink','kickledge','kickledge2')", "'dominolink','kickledge','kickledge2','pickpocket','bodyloot')")
rep("kickledge2=10000;", "kickledge2=10000;pickpocket=6500;bodyloot=13500;")
rep("}elseif($case-in'kickledge','kickledge2'){", """}elseif($case-in'pickpocket','bodyloot'){
    $lw=[Diagnostics.Stopwatch]::StartNew();$still=$false
    do{$l0=@((Q $source '--world-npcs').npcs|Where-Object {$_.spawnerName-eq'ld_spawner_guard_tutorial_2'})
     if($l0.Count-and[Math]::Sqrt([Math]::Pow([double]$l0[0].position[0]+47.95,2)+[Math]::Pow([double]$l0[0].position[1]+152.45,2))-lt.4){Start-Sleep -Milliseconds 600
      $l1=@((Q $source '--world-npcs').npcs|Where-Object {$_.spawnerName-eq'ld_spawner_guard_tutorial_2'});if($l1.Count-and[Math]::Sqrt([Math]::Pow([double]$l1[0].position[0]-[double]$l0[0].position[0],2)+[Math]::Pow([double]$l1[0].position[1]-[double]$l0[0].position[1],2))-lt.03){$still=$true}}
     else{Start-Sleep -Milliseconds 500}}while(!$still-and$lw.ElapsedMilliseconds-lt150000)
    if(!$still){throw 'Guard 2 never stood still at his patrol pause'};$row.guardWaitMs=$lw.ElapsedMilliseconds;$lg=$l1[0];$row.guard=$lg.position
    $gx=[double]$lg.position[0];$gy=[double]$lg.position[1];$lfx=[double]$lg.orientation[0];$lfy=[double]$lg.orientation[1];$lfl=[Math]::Max(1e-3,[Math]::Sqrt($lfx*$lfx+$lfy*$lfy));$lfx/=$lfl;$lfy/=$lfl
    $cx=$gx+3.6*$lfx;$cy=$gy+3.6*$lfy;$cz=[double]$lg.position[2]+1.9;$cyaw=[Math]::Atan2($gy-$cy,$gx-$cx)*180/[Math]::PI;$row.camera=@($cx,$cy,$cz)
    $op=(Q $peer '--player').candidatePosition;C $peer ('setviewpos {0} {1} {2} {3} 0' -f (F $op[0]),(F $op[1]),(F ([double]$op[2]+1.7)),(F $cyaw));Start-Sleep -Milliseconds 300
    try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $peer -Pitch 15 -Quick|Out-Null}catch{}
    C $peer ('coop_observer_camera hold_at {0} {1} {2}' -f (F $cx),(F $cy),(F $cz));Start-Sleep -Milliseconds 300
    $row.itemsBefore=@((Q $source '--player-inventory').items|Where-Object {$_.quantity-gt0}|ForEach-Object {"$($_.name)=$($_.quantity)"})
    & "$lab/Send-D2Input.ps1" -Role $source -Button B -DurationMs 150|Out-Null;Start-Sleep -Milliseconds 500
    if($case-eq'pickpocket'){$sx=$gx+.85*$lfy-.4*$lfx;$sy=$gy-.85*$lfx-.4*$lfy}else{$sx=$gx-.9*$lfx;$sy=$gy-.9*$lfy}
    $syaw=[Math]::Atan2($gy-$sy,$gx-$sx)*180/[Math]::PI
    C $source ('setviewpos {0} {1} 68.1 {2} 0' -f (F $sx),(F $sy),(F $syaw));& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch $(if($case-eq'pickpocket'){20}else{0}) -Quick|Out-Null
   }elseif($case-in'kickledge','kickledge2'){""")
rep("'stairs','dominolink','kickledge','kickledge2',", "'stairs','dominolink','kickledge','kickledge2','pickpocket','bodyloot',")
rep("""    if($case-eq'kickledge2'){""", """    if($case-eq'pickpocket'){
     if($step-eq0-and$t-ge900){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='pickpocket'});$step=1}}
    if($case-eq'bodyloot'){
     if($step-eq0-and$t-ge900){& "$lab/Send-D2Input.ps1" -Role $source -Button RightShoulder -DurationMs 6500|Out-Null;$segments.Add(@{ms=$t;loot='choke'});$step=1}
     elseif($step-eq1-and$t-ge8600){& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 50 -Quick|Out-Null;$step=2}
     elseif($step-eq2-and$t-ge9300){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='search body'});$step=3}
     elseif($step-eq3-and$t-ge10800-and!@($samples|Where-Object {$_.active -contains 47}).Count){& "$lab/Send-D2Input.ps1" -Role $source -Button X -DurationMs 300|Out-Null;$segments.Add(@{ms=$t;loot='search body again'});$step=4}}
    if($case-eq'kickledge2'){""")
rep("""    if($case-in'kickledge','kickledge2'){C $peer 'coop_observer_camera off';""", """    if($case-in'pickpocket','bodyloot'){C $peer 'coop_observer_camera off';try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 0 -Quick|Out-Null}catch{}
     $row.itemsAfter=@((Q $source '--player-inventory').items|Where-Object {$_.quantity-gt0}|ForEach-Object {"$($_.name)=$($_.quantity)"})
     $row.gained=@($row.itemsAfter|Where-Object {$_-notin$row.itemsBefore})
     $row.lootSamples=@($samples|Where-Object {$_.active -contains 47}).Count;$row.reachSamples=@($samples|Where-Object {[int]$_.useVariant-eq1-and[double]$_.useWeight-gt.5}).Count
     if(!$row.lootSamples){throw "No native loot (LootObject47) on the source"};if($case-eq'pickpocket'-and!$row.gained.Count){throw 'The pickpocket gained no item'}
     if($row.reachSamples-lt2){throw "Partner use reach presented in $($row.reachSamples) samples"}
     $row.checks.Add("Native $case ($($row.lootSamples) LootObject samples$(if($row.gained.Count){', gained '+($row.gained-join ', ')})); partner use reach in $($row.reachSamples) samples")}
    if($case-in'kickledge','kickledge2'){C $peer 'coop_observer_camera off';""")
rep("if($case-notin'kick','kickledge','kickledge2','crouchheavy'", "if($case-notin'kick','kickledge','kickledge2','pickpocket','bodyloot','crouchheavy'")
rep("scope='The native kick with the railing behind an alerted guard (1356, #11)", "scope='Pickpocket and body loot on the standing tutorial guard (1357, #11), the native kick with the railing behind an alerted guard (1356)")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1357.ps1').write_bytes(out.encode('utf-8'))
print('ok')
